PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def validate_png(data):
    """Full PNG validation: signature, IHDR, every chunk's CRC, IEND,
    and a complete zlib decompression of the IDAT stream (proves the
    image data is whole, not just well-formed headers)."""
    if not data.startswith(PNG_SIGNATURE):
        raise ValueError("not a PNG file")
    if len(data) < 33:
        raise ValueError("PNG too short for IHDR")
    width, height = struct.unpack(">II", data[16:24])
    if (width, height) != (1024, 1024):
        raise ValueError("unexpected dimensions %dx%d" % (width, height))
    if data[24] != 8:
        raise ValueError("bit depth is not 8")
    color_type = data[25]
    if color_type not in (2, 6):
        raise ValueError("color type is not RGB/RGBA")
    pos = 8
    idat = bytearray()
    seen_iend = False
    while pos < len(data):
        if pos + 8 > len(data):
            raise ValueError("truncated chunk header")
        length = struct.unpack(">I", data[pos:pos + 4])[0]
        ctype = data[pos + 4:pos + 8]
        if pos + 12 + length > len(data):
            raise ValueError("truncated chunk %r" % ctype)
        chunk_data = data[pos + 8:pos + 8 + length]
        crc_stored = struct.unpack(">I", data[pos + 8 + length:pos + 12 + length])[0]
        crc_calc = zlib.crc32(ctype)
        crc_calc = zlib.crc32(chunk_data, crc_calc)
        if crc_calc != crc_stored:
            raise ValueError("bad CRC in chunk %r" % ctype)
        if ctype == b"IDAT":
            idat += chunk_data
        if ctype == b"IEND":
            seen_iend = True
            break
        pos += 12 + length
    if not seen_iend:
        raise ValueError("no IEND chunk")
    zlib.decompress(bytes(idat))


def main():
    data = base64.b64decode("".join(POSTER_B64))
    validate_png(data)
    digest = hashlib.sha256(data).hexdigest()
    os.makedirs("/output", exist_ok=True)
    with open("/output/entry.png", "wb") as f:
        f.write(data)
    written = open("/output/entry.png", "rb").read()
    if hashlib.sha256(written).hexdigest() != digest:
        raise ValueError("written file does not match embedded poster")
    print("wrote /output/entry.png (%d bytes, sha256 %s)" % (len(data), digest))


if __name__ == "__main__":
    main()
